begin;
create or replace function public.rate_booking(p_booking bigint,p_stars integer,p_tags text[] default '{}',p_comment text default null) returns public.bookings language plpgsql security definer set search_path=public as $$ declare b bookings; begin select * into b from bookings where id=p_booking for update; if b.id is null or b.passenger_id is distinct from auth.uid() then raise exception 'Not your booking'; end if; if b.status not in ('onboard','done') or b.stars is not null then raise exception 'Finish the trip first or already rated'; end if; if p_stars is null or p_stars<1 or p_stars>5 then raise exception 'Invalid stars'; end if; update bookings set status='done',stars=p_stars,tags=p_tags,finished_at=coalesce(finished_at,now()),comment=nullif(left(coalesce(p_comment,''),500),'') where id=b.id returning * into b; return b; end; $$;
create or replace function public.rate_booking(p_booking bigint,p_stars integer,p_tags text[] default '{}') returns public.bookings language sql security definer set search_path=public as $$ select public.rate_booking(p_booking,p_stars,p_tags,null); $$;
commit;
